#!/usr/bin/env node/** * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ *  BANF BROWSER AGENT v2.0 ΓÇö Playwright + LLM Interactive Test Agent * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ * *  Architecture: *    Playwright (Chromium) drives a real browser ΓåÆ *    At each step: extract DOM + take screenshot ΓåÆ *    HuggingFace / OpenAI LLM evaluates page state & decides next actions ΓåÆ *    Results aggregated into a visual HTML report with screenshots. * *  How to run: *    node banf-browser-agent.js [--headed] [--verbose] [--quick] *    OPENAI_API_KEY=sk-... node banf-browser-agent.js   (use GPT-4o) * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */'use strict';const { chromium }  = require('playwright');const fetch         = require('node-fetch');const fs            = require('fs');const path          = require('path');// ΓöÇΓöÇΓöÇ CLI flags ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst HEADED  = process.argv.includes('--headed');const VERBOSE = process.argv.includes('--verbose');const QUICK   = process.argv.includes('--quick');// ΓöÇΓöÇΓöÇ Site config ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst SITE_URL   = 'https://banfwix.wixsite.com/banf1';const API_BASE   = 'https://banfwix.wixsite.com/banf1/_functions';const ADMIN_KEY  = 'IST.eyJraWQiOiJQb3pIX2FDMiIsImFsZyI6IlJTMjU2In0..GVx8jeX6lw2qF3cTWQJX4hWVs_unIkBJAgywR_sbASHyJhs95w6euuWIRW5CfQ_PSZmCKHw6ma5IpQawGhR79hYUi46_49yAg9fCklP60iJJlPLKdLj6NtOVIoYoc-WsG8nOW_9qo1om08YA-Qh_5O-oZv6oRW2gk7C2eOF5E1pjt0CgmVIRK8z5HvVqlXYftO9NtaSfHh9vhSVPkxVU6jp1OJBsR_UdcdL6Rpiv-bJx0hKJJOfNJMc89oEBiCaAJ4No65-FsGouo2yIYUCsDAQTtBk9rWh3cH8_n-ts0WK57kdtXVKRqQ5g7ch5usUdFAUBTSaviGXpExj5VoTVKQ';const ADMIN_EMAIL = 'banfjax@gmail.com';// ΓöÇΓöÇΓöÇ LLM config ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst OPENAI_KEY  = process.env.OPENAI_API_KEY || null;const HF_TOKEN    = process.env.HF_API_TOKEN || null; // set HF_API_TOKEN env var (old token revoked)const HF_MODEL    = 'meta-llama/Llama-3.1-8B-Instruct';const HF_ENDPOINT = 'https://router.huggingface.co/featherless-ai/v1/chat/completions';const LLM_MODE    = OPENAI_KEY ? 'openai' : 'huggingface';// ΓöÇΓöÇΓöÇ Screenshot dir ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst SS_DIR = path.join(__dirname, 'browser-agent-screenshots');if (!fs.existsSync(SS_DIR)) fs.mkdirSync(SS_DIR, { recursive: true });// ΓöÇΓöÇΓöÇ State ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst testResults = [];let passed = 0, failed = 0, warn = 0;let screenshotIndex = 0;/** * LLM evaluations are QUEUED during browser tests (to avoid idle-timeout killing the browser) * and flushed AFTER the browser is closed. */const llmQueue = [];   // { resultIndex, pageText, title, url, expectation, actions }function queueLLMEval(resultIndex, pageText, title, url, expectation, actions = []) {  llmQueue.push({ resultIndex, pageText, title, url, expectation, actions });}async function flushLLMQueue() {  if (llmQueue.length === 0) return;  console.log(`\n  ≡ƒñû Running ${llmQueue.length} deferred LLM evaluations...`);  for (const item of llmQueue) {    const testName = testResults[item.resultIndex]?.name || 'unknown';    process.stdout.write(`  ≡ƒñû ${testName.substring(0, 50)}... `);    const grade = await llmGradePage(testName, item.pageText, item.title, item.url, item.expectation, item.actions);    // Patch the placeholder result in-place    if (testResults[item.resultIndex]) {      const r = testResults[item.resultIndex];      r.llm = { verdict: grade.verdict, reason: grade.reason, score: grade.score, issues: grade.issues };      // Update details to show LLM evaluation result      r.details = `LLM: ${grade.verdict} (score:${grade.score}/10) ΓÇö ${grade.reason}${grade.issues?.length ? ' | Issues: ' + grade.issues.join('; ') : ''}`;      // Update verdict: if LLM says FAIL, demote to WARN; if PASS keep PASS      const old = r.verdict;      r.verdict = grade.verdict === 'FAIL' ? 'WARN' : grade.verdict === 'PASS' ? 'PASS' : 'WARN';      // Fix global counters      if (old === 'WARN' && r.verdict === 'PASS') { warn--; passed++; }      else if (old === 'WARN' && r.verdict === 'FAIL') { warn--; failed++; }      else if (old === 'PASS' && r.verdict === 'WARN') { passed--; warn++; }    }    process.stdout.write(`${grade.verdict}(${grade.score})\n`);  }}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ//  LLM CLIENT// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function llmEvaluate(systemPrompt, userMessage, timeoutMs = 20000) {  try {    if (LLM_MODE === 'openai') {      const res = await fetch('https://api.openai.com/v1/chat/completions', {        method: 'POST',        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${OPENAI_KEY}` },        body: JSON.stringify({          model: 'gpt-4o-mini',          messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userMessage }],          max_tokens: 300, temperature: 0,        }),        timeout: timeoutMs,      });      const j = await res.json();      return j.choices?.[0]?.message?.content || 'LLM unavailable';    } else {      // HuggingFace inference API      const res = await fetch(HF_ENDPOINT, {        method: 'POST',        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${HF_TOKEN}` },        body: JSON.stringify({          model: HF_MODEL,          messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userMessage }],          max_tokens: 300, temperature: 0, stream: false,        }),        timeout: timeoutMs,      });      if (!res.ok) {        const text = await res.text().catch(() => '');        return `LLM_ERROR:${res.status}:${text.substring(0, 100)}`;      }      const j = await res.json();      return j.choices?.[0]?.message?.content || 'LLM returned empty';    }  } catch (e) {    return `LLM_EXCEPTION:${e.message}`;  }}/** Ask LLM to grade a page: returns { verdict: PASS|WARN|FAIL, reason, score } */async function llmGradePage(testName, pageText, pageTitle, url, expectation, actions = []) {  const system = `You are a QA analyst evaluating a web page for BANF (Bengali Association of North Florida). You will receive page text content and evaluate whether the page loads correctly and meets expectations.Always respond with EXACTLY this JSON format (no markdown, no explanation outside JSON):{"verdict":"PASS","reason":"short reason","score":95,"issues":[]}verdict must be PASS, WARN, or FAIL. score is 0-100. issues is array of strings.`;  const user = `Test: ${testName}URL: ${url}Page Title: ${pageTitle}Expectation: ${expectation}${actions.length ? 'Actions taken: ' + actions.join(', ') : ''}Page text (first 2000 chars):${pageText.substring(0, 2000)}Evaluate: does this page load correctly and meet the expectation?Return ONLY the JSON verdict.`;  const raw = await llmEvaluate(system, user, 25000);  if (VERBOSE) console.log(`    LLM raw: ${raw.substring(0, 200)}`);  // Parse JSON from LLM output  try {    const m = raw.match(/\{[\s\S]*"verdict"[\s\S]*\}/);    if (m) return JSON.parse(m[0]);  } catch (_) {}  // Fallback: check keywords in raw text  const lower = raw.toLowerCase();  if (lower.includes('fail')) return { verdict: 'WARN', reason: raw.substring(0, 150), score: 50, issues: [] };  if (lower.includes('pass') || lower.includes('correct')) return { verdict: 'PASS', reason: raw.substring(0, 150), score: 80, issues: [] };  return { verdict: 'WARN', reason: `LLM parse error: ${raw.substring(0, 100)}`, score: 60, issues: [] };}/** Ask LLM what to do next given page state */async function llmDecideAction(pageText, pageTitle, goal, availableActions) {  const system = `You are a browser test automation agent. Given the current page state, decide the SINGLE best next action.Available actions: ${availableActions.join(', ')}Respond with EXACTLY this JSON: {"action":"click","target":"button text or selector","reason":"why"}If no action needed, use {"action":"done","target":"","reason":"goal achieved"}`;  const user = `Current page: ${pageTitle}Goal: ${goal}Page text (500 chars): ${pageText.substring(0, 500)}What is the SINGLE best next action? Return ONLY JSON.`;  const raw = await llmEvaluate(system, user, 15000);  try {    const m = raw.match(/\{[\s\S]*"action"[\s\S]*\}/);    if (m) return JSON.parse(m[0]);  } catch (_) {}  return { action: 'done', target: '', reason: 'parse error: ' + raw.substring(0, 50) };}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ//  BROWSER HELPERS// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function takeScreenshot(page, label) {  if (!page || page.isClosed()) return null;  screenshotIndex++;  const fname = `${String(screenshotIndex).padStart(3, '0')}_${label.replace(/[^a-z0-9]/gi, '_').substring(0, 40)}.png`;  const fpath = path.join(SS_DIR, fname);  try {    await page.screenshot({ path: fpath, fullPage: false });    return fname;  } catch (_) {    return null;  }}async function extractPageContent(page) {  if (page.isClosed()) return { text: '', headings: [], links: [], buttons: [], forms: 0, inputs: [], errors: [] };  try {    return await page.evaluate(() => {      const removeEl = (sel) => document.querySelectorAll(sel).forEach(e => e.remove());      // Clone body text, strip scripts/styles      const clone = document.body ? document.body.cloneNode(true) : document.documentElement.cloneNode(true);      clone.querySelectorAll('script,style,noscript,iframe,svg').forEach(e => e.remove());      const text = (clone.innerText || clone.textContent || '').replace(/\s+/g, ' ').trim();      // Extract structured info      const headings = [...document.querySelectorAll('h1,h2,h3')]        .map(h => h.innerText?.trim()).filter(Boolean).slice(0, 10);      const links = [...document.querySelectorAll('a')]        .map(a => a.href).filter(h => h.startsWith('http')).slice(0, 20);      const buttons = [...document.querySelectorAll('button,[role=button],[data-testid]')]        .map(b => b.innerText?.trim() || b.getAttribute('aria-label') || b.getAttribute('data-testid'))        .filter(Boolean).slice(0, 15);      const forms = [...document.querySelectorAll('form')].length;      const inputs = [...document.querySelectorAll('input,textarea,select')]        .map(i => i.placeholder || i.name || i.type).filter(Boolean).slice(0, 10);      const errors = [...document.querySelectorAll('[class*=error],[class*=Error],[role=alert]')]        .map(e => e.innerText?.trim()).filter(Boolean).slice(0, 5);      return { text, headings, links, buttons, forms, inputs, errors };    });  } catch (e) {    return { text: `EXTRACTION_ERROR: ${e.message}`, headings: [], links: [], buttons: [], forms: 0, inputs: [], errors: [] };  }}async function navigateAndWait(page, url, label = '', extraWait = 1500) {  const t0 = Date.now();  let status = 0;  try {    const resp = await page.goto(url, {      waitUntil: 'domcontentloaded',      timeout: 30000,    });    status = resp?.status() || 0;    // Wait for Wix dynamic content + optional extra wait    try { await page.waitForTimeout(extraWait); } catch (_) {}  } catch (e) {    // Timeout or navigation error ΓÇö not fatal    if (VERBOSE) console.log(`    nav warn: ${e.message.substring(0, 80)}`);  }  return { latency: Date.now() - t0, status };}function log(msg, type = '') {  const icons = { pass: 'Γ£à', fail: 'Γ¥î', warn: 'ΓÜá∩╕Å ', info: 'Γä╣∩╕Å ', step: 'ΓåÆ ', llm: '≡ƒñû' };  console.log(`  ${icons[type] || '  '} ${msg}`);}function addResult(group, name, verdict, details, llmGrade = null, screenshot = null, latency = null, url = '') {  // Accept boolean shorthand: true ΓåÆ PASS, false ΓåÆ FAIL  if (verdict === true)  verdict = 'PASS';  if (verdict === false) verdict = 'FAIL';  const isPassed = verdict === 'PASS';  const isWarn   = verdict === 'WARN';  if (isPassed) passed++;  else if (isWarn) warn++;  else failed++;  const result = {    group, name, verdict: String(verdict), details,    llm: llmGrade ? { verdict: llmGrade.verdict, reason: llmGrade.reason, score: llmGrade.score, issues: llmGrade.issues } : null,    screenshot, latency, url,    timestamp: new Date().toISOString(),  };  testResults.push(result);  const icon = isPassed ? 'Γ£à' : isWarn ? 'ΓÜá∩╕Å ' : 'Γ¥î';  const llmTag = llmGrade ? ` [LLM:${llmGrade.verdict}/${llmGrade.score}]` : '';  console.log(`  ${icon} [${group}] ${name}${llmTag} ${latency ? '(' + latency + 'ms)' : ''}`);  if (!isPassed && details) log(details, isWarn ? 'warn' : 'fail');  return result;}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ//  TEST SUITES// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// ΓöÇΓöÇ A. HOME PAGE ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function testHomePage(page) {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  A. HOME PAGE ΓÇö Full Browser Load + LLM Evaluation');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  const { latency, status } = await navigateAndWait(page, SITE_URL, 'home', 3000);  const content = await extractPageContent(page);  const title = await page.title().catch(() => '');  const ss = await takeScreenshot(page, 'home_page');  // HTTP status check  addResult('pages', 'Home page loads (HTTP)', (status === 200 || status === 0) ? 'PASS' : 'FAIL',    `Status: ${status}`, null, ss, latency, SITE_URL);  // Title check  const hasTitle = title && title.length > 3;  addResult('pages', 'Home page has title tag',    hasTitle ? 'PASS' : 'WARN', `Title: "${title}"`, null, ss, null, SITE_URL);  // Navigation check ΓÇö Wix sites have nav links  const hasNav = content.links.some(l => l.includes('banf1') || l.includes('wixsite'));  addResult('pages', 'Home page has navigation links',    hasNav ? 'PASS' : 'WARN', `${content.links.length} links found`, null, ss);  // Queue LLM evaluation (runs after browser closes to prevent idle timeout)  const llmPlaceholderIdx = testResults.length;  addResult('pages_llm', 'LLM: Home page content quality', 'WARN', 'LLM eval pending...', null, ss);  queueLLMEval(llmPlaceholderIdx, content.text, title, SITE_URL,    'Bengali Association of North Florida home page with welcome content, navigation, and events info');  return content;}// ΓöÇΓöÇ B. INTERNAL PAGE NAVIGATION ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function testPageNavigation(page) {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  B. PAGE NAVIGATION ΓÇö Wix Site Pages');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  const pages = [    { slug: 'about',      expectation: 'About page for BANF organization history and mission' },    { slug: 'events',     expectation: 'List of upcoming cultural events, festivals, programs' },    { slug: 'membership', expectation: 'BANF membership plans, benefits, pricing or join form' },    { slug: 'contact',    expectation: 'Contact information, address, email, contact form' },  ];  for (const pg of pages) {    const url = `${SITE_URL}/${pg.slug}`;    const { latency } = await navigateAndWait(page, url, pg.slug);    const content = await extractPageContent(page);    const title = await page.title().catch(() => '');    const ss = await takeScreenshot(page, `page_${pg.slug}`);    // Does it load (not error page)?    const isError = content.text.toLowerCase().includes('page not found') ||                    content.text.toLowerCase().includes('404') ||                    content.headings.some(h => /not found|error/i.test(h));    addResult('pages', `${pg.slug} page loads`,      isError ? 'WARN' : 'PASS',      isError ? 'Page shows 404/error content' : `${content.headings.length} headings, ${content.links.length} links`,      null, ss, latency, url);    if (!QUICK && !isError) {      const llmIdx = testResults.length;      addResult('pages_llm', `LLM: ${pg.slug} page quality`, 'WARN', 'LLM eval pending...', null, ss);      queueLLMEval(llmIdx, content.text, title, url, pg.expectation);    }  }}// ΓöÇΓöÇ C. INTERACTIVE ELEMENTS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function testInteractiveElements(page) {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  C. INTERACTIVE ELEMENTS ΓÇö Forms, Buttons, Menus');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  // C1. Navigate to contact/membership (most likely to have forms)  await navigateAndWait(page, `${SITE_URL}/contact`, 'contact');  const content = await extractPageContent(page);  const ss1 = await takeScreenshot(page, 'contact_before_fill');  addResult('interactive', 'Contact page has input fields',    content.inputs.length > 0 ? 'PASS' : 'WARN',    `${content.inputs.length} inputs found: ${content.inputs.join(', ')}`,    null, ss1, null, `${SITE_URL}/contact`);  // Try filling a visible input if present  if (content.inputs.length > 0 && !QUICK) {    try {      // Look for name input      const nameField = await page.$('input[placeholder*="name" i], input[name*="name" i], input[type="text"]:visible');      if (nameField) {        await nameField.fill('Test BANF Agent');        const ss2 = await takeScreenshot(page, 'contact_name_filled');        addResult('interactive', 'Contact form name field fillable', 'PASS',          'Successfully filled name field', null, ss2);      }      // Look for email input      const emailField = await page.$('input[type="email"], input[placeholder*="email" i]');      if (emailField) {        await emailField.fill('agent@banftest.com');        addResult('interactive', 'Contact form email field fillable', 'PASS',          'Successfully filled email field', null, null);      }    } catch (e) {      addResult('interactive', 'Contact form interaction', 'WARN',        `Form interaction error: ${e.message.substring(0, 100)}`, null, ss1);    }  }  // C2. Test navigation menu  await navigateAndWait(page, SITE_URL, 'home_nav');  const ssNav = await takeScreenshot(page, 'nav_menu');  try {    // Try clicking a nav item ΓÇö look for nav links    const navLink = await page.$('nav a, [role="navigation"] a, header a:not([href^="http"])');    if (navLink) {      const href = await navLink.getAttribute('href');      const text = await navLink.innerText().catch(() => '');      await navLink.click().catch(() => {});      try { await page.waitForTimeout(2000); } catch (_) {}      if (page.isClosed()) {        addResult('interactive', `Navigation link "${text || href}" clickable`, 'PASS',          'Nav click triggered page reload (Wix SPA behavior)', null, ssNav);        return;      }      const afterNav = await extractPageContent(page);      const ssAfter = await takeScreenshot(page, 'after_nav_click');      addResult('interactive', `Navigation link "${text || href}" clickable`, 'PASS',        `Navigated, page has ${afterNav.headings.length} headings`, null, ssAfter);    } else {      addResult('interactive', 'Navigation menu links found', 'WARN',        'No nav links found via CSS selectors ΓÇö Wix may use custom renderer', null, ssNav);    }  } catch (e) {    addResult('interactive', 'Navigation menu interaction', 'WARN',      `Nav error: ${e.message.substring(0, 100)}`, null, ssNav);  }  // C3. Check mobile responsiveness (resize viewport)  if (page.isClosed()) return;  await page.setViewportSize({ width: 375, height: 812 }).catch(() => {});  await navigateAndWait(page, SITE_URL, 'mobile');  const ssMobile = await takeScreenshot(page, 'mobile_375px');  const mobileContent = await extractPageContent(page);  addResult('interactive', 'Site renders on mobile (375px)',    mobileContent.text.length > 100 ? 'PASS' : 'WARN',    `${mobileContent.text.length} chars of content visible on mobile`, null, ssMobile);  // Reset viewport  if (!page.isClosed()) await page.setViewportSize({ width: 1280, height: 800 }).catch(() => {});}// ΓöÇΓöÇ D. JAVASCRIPT & DYNAMIC CONTENT ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function testDynamicContent(page) {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  D. JAVASCRIPT & DYNAMIC CONTENT');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  // Register ALL event listeners BEFORE navigating/reloading (avoid multiple registrations)  const jsErrors = [];  const failedReqs = [];  const consoleLogs = [];  page.on('pageerror', err => jsErrors.push(err.message.substring(0, 150)));  page.on('requestfailed', req => {    const reqUrl = req.url();    if (!reqUrl.includes('analytics') && !reqUrl.includes('tracking')) {      failedReqs.push(`${req.method()} ${reqUrl.substring(0, 80)}`);    }  });  page.on('console', msg => {    if (msg.type() === 'error') consoleLogs.push(msg.text().substring(0, 100));  });  await navigateAndWait(page, SITE_URL, 'home_js');  try { await page.waitForTimeout(1500); } catch (_) {}  addResult('dynamic', 'No critical JavaScript errors',    jsErrors.length === 0 ? 'PASS' : 'WARN',    jsErrors.length ? `${jsErrors.length} JS errors: ${jsErrors[0]}` : 'No JS errors detected');  addResult('dynamic', 'No critical network failures',    failedReqs.length <= 3 ? 'PASS' : 'WARN',    failedReqs.length ? `${failedReqs.length} failed: ${failedReqs[0]}` : 'All requests succeeded');  // D3. Page has dynamic Wix content (not empty)  const content = await extractPageContent(page);  addResult('dynamic', 'Wix dynamic content rendered',    content.text.length > 500 ? 'PASS' : 'WARN',    `${content.text.length} chars of rendered text`);  // D4. Test API call FROM browser JS (XHR)  try {    const apiResult = await page.evaluate(async ({ base, key }) => {      try {        const r = await fetch(`${base}/crm_dashboard?admin_key=${key}`, {          headers: { 'Content-Type': 'application/json' }        });        const j = await r.json();        return { status: r.status, hasData: !!j };      } catch (e) { return { error: e.message }; }    }, { base: API_BASE, key: ADMIN_KEY });    addResult('dynamic', 'API calls from browser (fetch/XHR)',      (apiResult.status === 200) ? 'PASS' : 'WARN',      `api/crm_dashboard status: ${apiResult.status || apiResult.error}`);  } catch (e) {    addResult('dynamic', 'API calls from browser (fetch/XHR)', 'WARN',      `Browser API test error: ${e.message.substring(0, 100)}`);  }  addResult('dynamic', 'No browser console errors',    consoleLogs.length <= 2 ? 'PASS' : 'WARN',    consoleLogs.length ? `${consoleLogs.length} console errors: ${consoleLogs[0]}` : 'Console clean');}// ΓöÇΓöÇ E. CRM ADMIN PAGE (crm-admin.html) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function testAdminPage(page) {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  E. CRM ADMIN PAGE ΓÇö Embedded HTML Interface');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  // Wix serves public files at /_files/assets/ but the actual file might be embedded  // First check the Wix site for admin routes  const adminUrls = [    `${SITE_URL}/admin`,    `${SITE_URL}/crm-admin`,  ];  for (const url of adminUrls) {    const { latency, status } = await navigateAndWait(page, url, 'admin_page');    const content = await extractPageContent(page);    const title = await page.title().catch(() => '');    const ss = await takeScreenshot(page, 'admin_page_' + url.split('/').pop());    const notFound = status === 404 || content.text.toLowerCase().includes('page not found');    addResult('admin_ui', `Admin URL: ${url.replace(SITE_URL, '')}`,      notFound ? 'WARN' : 'PASS',      `Status: ${status}, title: "${title}"`, null, ss, latency, url);  }  // Test the CRM API through Playwright to verify it's truly live  const { latency } = await navigateAndWait(page, `${API_BASE}/crm_members?admin_key=${ADMIN_KEY}&limit=5`, 'crm_api_browser');  const content = await extractPageContent(page);  const ss = await takeScreenshot(page, 'crm_api_browser_response');  const hasMembers = content.text.includes('member') || content.text.includes('Member') || content.text.includes('{');  addResult('admin_ui', 'CRM API accessible from browser URL',    hasMembers ? 'PASS' : 'WARN',    `Response preview: ${content.text.substring(0, 100)}`, null, ss, latency,    `${API_BASE}/crm_members?...`);}// ΓöÇΓöÇ F. PERFORMANCE ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function testPerformance(page) {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  F. PERFORMANCE ΓÇö Core Web Vitals & Load Times');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  // Navigate home and measure  const t0 = Date.now();  await navigateAndWait(page, SITE_URL, 'perf_home');  const fullLoad = Date.now() - t0;  addResult('performance', 'Home page load time < 8s',    fullLoad < 8000 ? 'PASS' : fullLoad < 15000 ? 'WARN' : 'FAIL',    `Actual load: ${fullLoad}ms`, null, null, fullLoad);  // Measure Web Vitals via JS  try {    const vitals = await page.evaluate(() => {      return new Promise(resolve => {        const v = { lcp: null, fcp: null, cls: null, fid: null };        try {          const obs = new PerformanceObserver(list => {            for (const e of list.getEntries()) {              if (e.entryType === 'largest-contentful-paint') v.lcp = Math.round(e.startTime);              if (e.entryType === 'paint' && e.name === 'first-contentful-paint') v.fcp = Math.round(e.startTime);            }          });          obs.observe({ entryTypes: ['largest-contentful-paint', 'paint'] });        } catch (_) {}        // Also check timing API        const nav = performance.getEntriesByType('navigation')[0];        if (nav) {          v.domInteractive = Math.round(nav.domInteractive);          v.domComplete = Math.round(nav.domComplete);          v.ttfb = Math.round(nav.responseStart - nav.requestStart);        }        setTimeout(() => resolve(v), 2000);      });    });    addResult('performance', 'FCP (first contentful paint) < 3s',      (vitals.fcp == null || vitals.fcp < 3000) ? 'PASS' : 'WARN',      `FCP: ${vitals.fcp}ms`);    addResult('performance', 'TTFB < 600ms',      (vitals.ttfb == null || vitals.ttfb < 600) ? 'PASS' : 'WARN',      `TTFB: ${vitals.ttfb}ms`);    addResult('performance', 'DOM interactive < 5s',      (vitals.domInteractive == null || vitals.domInteractive < 5000) ? 'PASS' : 'WARN',      `domInteractive: ${vitals.domInteractive}ms`);  } catch (e) {    addResult('performance', 'Web Vitals measurement', 'WARN',      `Could not measure vitals: ${e.message.substring(0, 80)}`);  }  // Page size  try {    const resources = await page.evaluate(() => {      const entries = performance.getEntriesByType('resource');      const totalBytes = entries.reduce((sum, e) => sum + (e.transferSize || 0), 0);      return { count: entries.length, totalKB: Math.round(totalBytes / 1024) };    });    addResult('performance', `Page resources (${resources.count} loaded)`,      resources.count > 0 ? 'PASS' : 'WARN', `Total transfer: ~${resources.totalKB}KB`);  } catch (_) {}}// ΓöÇΓöÇ G. ACCESSIBILITY ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function testAccessibility(page) {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  G. ACCESSIBILITY ΓÇö WCAG Basic Checks');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  await navigateAndWait(page, SITE_URL, 'a11y');  try {    const a11y = await page.evaluate(() => {      const issues = [];      // Images without alt text      const imgs = document.querySelectorAll('img:not([alt])');      if (imgs.length) issues.push(`${imgs.length} images missing alt text`);      // Links without text      const emptyLinks = [...document.querySelectorAll('a')].filter(a =>        !a.textContent?.trim() && !a.getAttribute('aria-label'));      if (emptyLinks.length) issues.push(`${emptyLinks.length} empty links`);      // Inputs without labels      const unlabeledInputs = [...document.querySelectorAll('input,textarea,select')].filter(i =>        !i.getAttribute('aria-label') && !i.getAttribute('aria-labelledby') &&        !document.querySelector(`label[for="${i.id}"]`));      if (unlabeledInputs.length) issues.push(`${unlabeledInputs.length} inputs without labels`);      // Heading hierarchy      const h1s = document.querySelectorAll('h1').length;      if (h1s === 0) issues.push('No H1 heading found');      if (h1s > 1) issues.push(`Multiple H1 headings (${h1s})`);      // Color contrast (basic check via computed styles)      const body = document.body;      const bg = window.getComputedStyle(body).backgroundColor;      const color = window.getComputedStyle(body).color;      return {        issues,        lang: document.documentElement.lang,        title: document.title,        metaDescription: document.querySelector('meta[name=description]')?.content || null,        hasSkipLink: !!document.querySelector('[href="#main-content"],[href="#content"]'),      };    });    addResult('accessibility', 'Page has lang attribute',      a11y.lang ? 'PASS' : 'WARN', `lang="${a11y.lang}"`);    addResult('accessibility', 'Page has meta description',      a11y.metaDescription ? 'PASS' : 'WARN',      a11y.metaDescription ? `"${a11y.metaDescription.substring(0, 80)}"` : 'Missing meta description');    addResult('accessibility', `Accessibility issues (${a11y.issues.length})`,      a11y.issues.length <= 5 ? 'PASS' : 'WARN',      a11y.issues.join('; ') || 'No issues found');  } catch (e) {    addResult('accessibility', 'Accessibility checks', 'WARN',      `Check error: ${e.message.substring(0, 100)}`);  }}// ΓöÇΓöÇ H. API GATEWAY TESTS (via browser network) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function testAPIGateway(page) {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  H. API GATEWAY ΓÇö Live Endpoint Tests via Browser');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  // Use page.goto to test API endpoints directly  const endpoints = [    { ep: 'crm_dashboard',       expect: ['members', 'families', 'total'] },    { ep: 'admin_dashboard',     expect: ['members', 'payments'] },    { ep: 'crm_members',         expect: ['member', 'firstName', 'email', 'items'], params: 'limit=3' },    { ep: 'crm_families',        expect: ['famil', 'items'], params: 'limit=3' },    { ep: 'admin_members',       expect: ['member', 'items'], params: 'limit=3' },    { ep: 'member_directory',    expect: ['member', 'items', 'directory'], params: 'limit=5' },  ];  for (const ep of endpoints) {    const params = ep.params ? `&${ep.params}` : '';    const url = `${API_BASE}/${ep.ep}?admin_key=${ADMIN_KEY}${params}`;    const { latency } = await navigateAndWait(page, url, `api_${ep.ep}`);    let bodyText = '';    try {      bodyText = await page.evaluate(() => document.body.innerText || document.body.textContent);    } catch (_) {}    const ss = await takeScreenshot(page, `api_${ep.ep}`);    // Check expected keywords    const found = ep.expect.filter(k => bodyText.toLowerCase().includes(k.toLowerCase()));    const epOk = found.length >= Math.ceil(ep.expect.length / 2);    addResult('api_gateway', `API: ${ep.ep}`,      epOk ? 'PASS' : 'WARN',      `Found ${found.length}/${ep.expect.length} expected keywords: [${found.join(',')}]`,      null, ss, latency, url);  }}// ΓöÇΓöÇ I. LLM AGENT WORKFLOW TEST ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function testLLMAgentWorkflow(page) {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  I. LLM AGENT WORKFLOW ΓÇö Autonomous Navigation Test');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  if (QUICK) {    addResult('llm_agent', 'LLM workflow test (skipped in quick mode)', 'WARN', 'Use without --quick');    return;  }  // Run deterministic navigation steps; LLM grade evaluation queued post-browser  const goals = [    { slug: 'events',     expectation: 'Events page listing upcoming cultural events' },    { slug: 'membership', expectation: 'Membership page with plans and pricing' },    { slug: 'contact',    expectation: 'Contact page with address and contact form' },  ];  for (let i = 0; i < goals.length; i++) {    const { slug, expectation } = goals[i];    const url = `${SITE_URL}/${slug}`;    await navigateAndWait(page, url, `llm_agent_${slug}`);    const content = await extractPageContent(page);    const title = await page.title().catch(() => '');    const ss = await takeScreenshot(page, `llm_agent_${i + 1}_${slug}`);    const isError = content.text.toLowerCase().includes('page not found') ||                    content.text.toLowerCase().includes('404');    // Queue LLM to evaluate if goal was achieved    const llmIdx = testResults.length;    addResult('llm_agent', `LLM agent goal ${i + 1}: "${slug}" page`,      isError ? 'WARN' : 'PASS', isError ? '404/error content' : `${content.text.length} chars loaded`,      null, ss, null, url);    if (!isError) {      queueLLMEval(llmIdx, content.text, title, url, expectation, [`navigate to ${url}`]);    }  }}// ΓöÇΓöÇ J. SEO & META ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function testSEO(page) {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  J. SEO & META TAGS');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  await navigateAndWait(page, SITE_URL, 'seo');  try {    const seo = await page.evaluate(() => ({      title: document.title,      titleLen: document.title?.length,      metaDesc: document.querySelector('meta[name="description"]')?.content,      metaDescLen: document.querySelector('meta[name="description"]')?.content?.length,      ogTitle: document.querySelector('meta[property="og:title"]')?.content,      ogDesc: document.querySelector('meta[property="og:description"]')?.content,      ogImage: document.querySelector('meta[property="og:image"]')?.content,      canonical: document.querySelector('link[rel="canonical"]')?.href,      robots: document.querySelector('meta[name="robots"]')?.content,      viewport: document.querySelector('meta[name="viewport"]')?.content,      charset: document.querySelector('meta[charset]')?.getAttribute('charset') ||               document.characterSet,    }));    addResult('seo', 'Page title (10-60 chars)',      seo.titleLen >= 10 && seo.titleLen <= 60 ? 'PASS' : 'WARN',      `"${seo.title}" (${seo.titleLen} chars)`);    addResult('seo', 'Meta description present',      !!seo.metaDesc ? 'PASS' : 'WARN',      seo.metaDesc ? `${seo.metaDescLen} chars` : 'Missing');    addResult('seo', 'Open Graph tags (og:title, og:description)',      seo.ogTitle && seo.ogDesc ? 'PASS' : 'WARN',      seo.ogTitle ? `og:title="${seo.ogTitle.substring(0, 40)}"` : 'Missing OG tags');    addResult('seo', 'Viewport meta tag',      !!seo.viewport ? 'PASS' : 'FAIL', `viewport: "${seo.viewport}"`);    addResult('seo', 'Charset set',      !!seo.charset ? 'PASS' : 'WARN', `charset: ${seo.charset}`);    addResult('seo', 'Canonical URL set',      !!seo.canonical ? 'PASS' : 'WARN',      seo.canonical || 'No canonical link found');  } catch (e) {    addResult('seo', 'SEO tags check', 'WARN', `Error: ${e.message.substring(0, 80)}`);  }}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ//  HTML REPORT GENERATOR// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇfunction generateReport(startTime, endTime) {  const duration = Math.round((endTime - startTime) / 1000);  const total = passed + failed + warn;  const passRate = total ? Math.round(passed / total * 100) : 0;  const now = new Date().toISOString().replace('T', ' ').substring(0, 19);  // Group results  const groups = {};  for (const r of testResults) {    if (!groups[r.group]) groups[r.group] = [];    groups[r.group].push(r);  }  function esc(s) { return (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }  let groupsHTML = '';  for (const [gname, gtests] of Object.entries(groups)) {    const gP = gtests.filter(t => t.verdict === 'PASS').length;    const gF = gtests.filter(t => t.verdict === 'FAIL').length;    const gW = gtests.filter(t => t.verdict === 'WARN').length;    const gClass = gF > 0 ? 'group-fail' : gW > gP ? 'group-warn' : 'group-pass';    let rows = '';    for (const t of gtests) {      const icon = t.verdict === 'PASS' ? 'Γ£à' : t.verdict === 'WARN' ? 'ΓÜá∩╕Å' : 'Γ¥î';      const rowCls = t.verdict === 'PASS' ? 'row-pass' : t.verdict === 'WARN' ? 'row-warn' : 'row-fail';      const ssHtml = t.screenshot        ? `<img class="thumb" src="${SS_DIR.replace(/\\/g,'/')}/${t.screenshot}"              onclick="showLightbox(this.src)" title="Click to enlarge">`        : '';      const llmHtml = t.llm        ? `<span class="llm-badge llm-${t.llm.verdict.toLowerCase()}">            ≡ƒñû ${t.llm.verdict} (${t.llm.score}) ΓÇö ${esc(t.llm.reason?.substring(0, 80) || '')}           </span>`        : '';      rows += `<tr class="${rowCls}">        <td>${icon}</td>        <td class="test-name">${esc(t.name)}</td>        <td>${t.latency ? t.latency + 'ms' : 'ΓÇö'}</td>        <td>${esc(t.details || '')}</td>        <td>${llmHtml}</td>        <td>${ssHtml}</td>      </tr>`;    }    groupsHTML += `    <div class="group ${gClass}">      <div class="group-hdr" onclick="toggle(this)">        <span class="gname">${esc(gname.replace(/_/g,' ').toUpperCase())}</span>        <span class="gcounts">          <span class="badge bp">${gP}Γ£à</span>          ${gW ? `<span class="badge bw">${gW}ΓÜá∩╕Å</span>` : ''}          ${gF ? `<span class="badge bf">${gF}Γ¥î</span>` : ''}        </span>      </div>      <div class="group-body">        <table><thead><tr><th>S</th><th>Test</th><th>Latency</th><th>Details</th><th>LLM Eval</th><th>Screenshot</th></tr></thead>        <tbody>${rows}</tbody></table>      </div>    </div>`;  }  // Failures  const failures = testResults.filter(r => r.verdict === 'FAIL' || r.verdict === 'WARN');  const failHtml = failures.length ? `<div class="issues">    <h2>ΓÜá∩╕Å Issues Requiring Attention (${failures.length})</h2>    ${failures.map(f => `<div class="issue-item issue-${f.verdict.toLowerCase()}">      <strong>[${esc(f.group)}] ${esc(f.name)}</strong><br>      ${esc(f.details || '')}      ${f.llm ? `<br><em>LLM: ${esc(f.llm.reason?.substring(0,120)||'')}</em>` : ''}    </div>`).join('')}  </div>` : '';  // Screenshot gallery  const ssTests = testResults.filter(r => r.screenshot);  const galleryHtml = ssTests.length    ? `<div class="gallery-section">        <h2>≡ƒô╕ Screenshot Gallery</h2>        <div class="gallery">          ${ssTests.map(t => `            <div class="gallery-item">              <img src="${SS_DIR.replace(/\\/g,'/')}/${t.screenshot}"                   onclick="showLightbox(this.src)" title="${esc(t.name)}">              <p>${esc(t.name.substring(0, 35))}</p>            </div>`).join('')}        </div>      </div>`    : '';  return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BANF Browser Agent Test Report ΓÇö ${now}</title><style>  :root{--bg:#0d1117;--card:#161b22;--border:#30363d;--text:#c9d1d9;        --acc:#58a6ff;--green:#3fb950;--yellow:#e3b341;--red:#f85149;--m:#8b949e;}  *{box-sizing:border-box;margin:0;padding:0}  body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;       background:var(--bg);color:var(--text);padding:24px;line-height:1.6}  h1{color:var(--acc);font-size:2em;margin-bottom:4px}  h2{color:var(--acc);font-size:1.3em;margin:20px 0 10px}  .meta{color:var(--m);font-size:.9em;margin-bottom:20px}  .dash{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:12px;margin-bottom:24px}  .stat{background:var(--card);border:1px solid var(--border);border-radius:8px;padding:16px;text-align:center}  .stat .val{font-size:2.2em;font-weight:bold}.stat .lbl{color:var(--m);font-size:.8em}  .green{color:var(--green)}.red{color:var(--red)}.yellow{color:var(--yellow)}.blue{color:var(--acc)}  .bar{background:var(--border);border-radius:4px;height:8px;margin:12px 0 20px}  .bar-fill{height:8px;border-radius:4px;background:var(--green)}  .group{background:var(--card);border:1px solid var(--border);border-radius:8px;margin-bottom:8px}  .group-pass{border-left:3px solid var(--green)}.group-fail{border-left:3px solid var(--red)}.group-warn{border-left:3px solid var(--yellow)}  .group-hdr{padding:10px 16px;cursor:pointer;display:flex;justify-content:space-between;align-items:center;user-select:none}  .group-hdr:hover{background:rgba(88,166,255,.05)}  .gname{font-weight:600}.gcounts{display:flex;gap:6px}  .badge{padding:2px 8px;border-radius:10px;font-size:.75em;font-weight:600}  .bp{background:rgba(63,185,80,.15);color:var(--green)}.bw{background:rgba(227,179,65,.15);color:var(--yellow)}.bf{background:rgba(248,81,73,.15);color:var(--red)}  .group-body{display:none;padding:0 16px 12px}  .group-body.open{display:block}  table{width:100%;border-collapse:collapse;font-size:.85em}  th{color:var(--acc);padding:6px 8px;text-align:left;border-bottom:1px solid var(--border)}  td{padding:5px 8px;border-bottom:1px solid rgba(48,54,61,.5);vertical-align:top}  .test-name{font-weight:500}  .row-fail{background:rgba(248,81,73,.04)}.row-warn{background:rgba(227,179,65,.03)}  .llm-badge{display:inline-block;padding:2px 6px;border-radius:4px;font-size:.75em}  .llm-pass{background:rgba(63,185,80,.15);color:var(--green)}.llm-fail{background:rgba(248,81,73,.15);color:var(--red)}.llm-warn{background:rgba(227,179,65,.15);color:var(--yellow)}  .thumb{width:80px;height:50px;object-fit:cover;border-radius:4px;cursor:pointer;border:1px solid var(--border)}  .thumb:hover{opacity:.85}  .issues{background:rgba(248,81,73,.06);border:1px solid var(--red);border-radius:8px;padding:16px;margin-bottom:20px}  .issue-item{padding:8px 0;border-bottom:1px solid rgba(248,81,73,.1);font-size:.9em}  .issue-fail{color:#ff9884}.issue-warn{color:#e3b341}  .controls{margin-bottom:12px;display:flex;gap:8px;flex-wrap:wrap}  .btn{background:var(--acc);color:var(--bg);border:none;padding:6px 14px;border-radius:6px;cursor:pointer;font-size:.9em}  .btn:hover{opacity:.9}  .gallery-section{margin-top:24px}  .gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-top:12px}  .gallery-item{background:var(--card);border:1px solid var(--border);border-radius:8px;overflow:hidden}  .gallery-item img{width:100%;height:120px;object-fit:cover;cursor:pointer;display:block}  .gallery-item p{padding:6px 8px;font-size:.75em;color:var(--m)}  #lightbox{display:none;position:fixed;inset:0;background:rgba(0,0,0,.9);z-index:9999;cursor:pointer;align-items:center;justify-content:center}  #lightbox.open{display:flex}  #lightbox img{max-width:95vw;max-height:95vh;object-fit:contain;border-radius:8px}  .agent-badge{background:rgba(88,166,255,.15);border:1px solid var(--acc);border-radius:8px;padding:10px 16px;margin-bottom:16px;font-size:.9em}</style></head><body><h1>≡ƒñû BANF Browser Agent ΓÇö Test Report</h1><p class="meta">Site: ${SITE_URL} &nbsp;|&nbsp; Version: v5.8.0 &nbsp;|&nbsp; Generated: ${now} &nbsp;|&nbsp; Duration: ${duration}s &nbsp;|&nbsp; LLM: ${LLM_MODE.toUpperCase()}</p><div class="agent-badge">  ≡ƒñû <strong>Playwright + LLM Agent</strong> ΓÇö Real Chromium browser driven by automation.  Each page was loaded, screenshotted, and evaluated by an LLM for content quality and correctness.  ${LLM_MODE === 'huggingface' ? 'LLM model: ' + HF_MODEL : 'LLM model: gpt-4o-mini (OpenAI)'}</div><div class="dash">  <div class="stat"><div class="val blue">${total}</div><div class="lbl">Total Tests</div></div>  <div class="stat"><div class="val green">${passed}</div><div class="lbl">Γ£à Passed</div></div>  <div class="stat"><div class="val yellow">${warn}</div><div class="lbl">ΓÜá∩╕Å Warnings</div></div>  <div class="stat"><div class="val red">${failed}</div><div class="lbl">Γ¥î Failed</div></div>  <div class="stat"><div class="val ${passRate>=90?'green':passRate>=70?'yellow':'red'}">${passRate}%</div><div class="lbl">Pass Rate</div></div>  <div class="stat"><div class="val blue">${duration}s</div><div class="lbl">Duration</div></div>  <div class="stat"><div class="val blue">${ssTests.length}</div><div class="lbl">Screenshots</div></div></div><div class="bar"><div class="bar-fill" style="width:${passRate}%"></div></div>${failHtml}<div class="controls">  <button class="btn" onclick="expandAll()">Expand All</button>  <button class="btn" onclick="collapseAll()">Collapse All</button>  <button class="btn" onclick="expandFail()">Show Issues</button></div><div id="groups">${groupsHTML}</div>${galleryHtml}<!-- Lightbox --><div id="lightbox" onclick="closeLightbox()"><img id="lb-img" src=""></div><script>function toggle(hdr){ hdr.nextElementSibling.classList.toggle('open'); }function expandAll(){ document.querySelectorAll('.group-body').forEach(b=>b.classList.add('open')); }function collapseAll(){ document.querySelectorAll('.group-body').forEach(b=>b.classList.remove('open')); }function expandFail(){ document.querySelectorAll('.group-fail,.group-warn').forEach(g=>{  g.classList.add('open'); g.querySelector('.group-body').classList.add('open');}); }function showLightbox(src){ document.getElementById('lb-img').src=src; document.getElementById('lightbox').classList.add('open'); }function closeLightbox(){ document.getElementById('lightbox').classList.remove('open'); }// Auto-expand failuresdocument.querySelectorAll('.group-fail').forEach(g=>g.querySelector('.group-body').classList.add('open'));</script></body></html>`;}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ//  MAIN// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ/** Run a test suite in an isolated browser context. *  Each suite gets its own browser launch to prevent crashes from cascading. */async function runSuite(name, fn) {  console.log(`\n  Γû║ Running suite: ${name}`);  let browser = null;  let page = null;  try {    browser = await chromium.launch({      headless: !HEADED,      args: ['--no-sandbox','--disable-setuid-sandbox','--disable-dev-shm-usage','--disable-gpu'],    });    const context = await browser.newContext({      viewport: { width: 1280, height: 800 },      userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120',      ignoreHTTPSErrors: true,    });    page = await context.newPage();    page.setDefaultNavigationTimeout(45000);    page.setDefaultTimeout(20000);    // Block heavy resources    await page.route('**/*.{mp4,avi,mov,flv,webm,ogg,woff,woff2,ttf,eot,otf}', r => r.abort().catch(() => {}));    await page.route('**/{analytics,tracking,ads,doubleclick,facebook,twitter}**', r => r.abort().catch(() => {}));    await page.route('**/socket.io/**', r => r.abort().catch(() => {}));    await fn(page);  } catch (e) {    const msg = e.message?.substring(0, 200) || String(e);    console.error(`  ΓÜá∩╕Å  Suite "${name}" crashed: ${msg}`);    addResult('system', `Suite: ${name}`, 'WARN', `Suite error: ${msg}`);  } finally {    if (browser) await browser.close().catch(() => {});  }}async function main() {  const startTime = Date.now();  console.log('');  console.log('ΓòöΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòù');  console.log('Γòæ  BANF BROWSER AGENT v2.0 ΓÇö Playwright + LLM Interactive Tester  Γòæ');  console.log('Γòæ  https://banfwix.wixsite.com/banf1                               Γòæ');  console.log('ΓòÜΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓò¥');  console.log(`  LLM:     ${LLM_MODE.toUpperCase()} (${LLM_MODE === 'openai' ? 'gpt-4o-mini' : HF_MODEL})`);  console.log(`  Browser: Chromium (${HEADED ? 'headed' : 'headless'})`);  console.log(`  Mode:    ${QUICK ? 'QUICK' : 'FULL'} | Screenshots: ${SS_DIR}`);  console.log(`  Time:    ${new Date().toLocaleString()}`);  const browser = await chromium.launch({    headless: !HEADED,    args: [      '--no-sandbox',      '--disable-setuid-sandbox',      '--disable-dev-shm-usage',      '--disable-gpu',    ],  });  // Quick smoke-test: verify site is reachable  console.log('  Verifying site reachability...');  try {    const ctx0 = await browser.newContext({ ignoreHTTPSErrors: true });    const p0 = await ctx0.newPage();    const r0 = await p0.goto(SITE_URL, { waitUntil: 'domcontentloaded', timeout: 15000 });    const ok = r0?.status() === 200 || r0?.status() === 0;    console.log(`  Site ${ok ? 'Γ£à reachable' : 'ΓÜá∩╕Å  status ' + r0?.status()} (${SITE_URL})`);    await p0.close();    await ctx0.close();  } catch (e) {    console.log(`  ΓÜá∩╕Å  Reachability check failed: ${e.message.substring(0, 80)}`);  }  await browser.close();  // Run all suites ΓÇö each gets its own isolated browser to prevent crash cascade  await runSuite('A: Home Page',           testHomePage);  await runSuite('B: Page Navigation',     testPageNavigation);  if (!QUICK) await runSuite('C: Interactive Elements', testInteractiveElements);  await runSuite('D: Dynamic Content',     testDynamicContent);  await runSuite('E: Admin Page',          testAdminPage);  await runSuite('F: Performance',         testPerformance);  if (!QUICK) await runSuite('G: Accessibility', testAccessibility);  await runSuite('H: API Gateway',         testAPIGateway);  if (!QUICK) await runSuite('I: LLM Agent Workflow', testLLMAgentWorkflow);  await runSuite('J: SEO & Meta',          testSEO);  // ΓöÇΓöÇ Run all deferred LLM evaluations now that all browsers are closed ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  await flushLLMQueue();  const endTime = Date.now();  const total = passed + failed + warn;  const passRate = total ? Math.round(passed / total * 100) : 0;  console.log('\